config.code:
{
  "agent": "general",
  "custom Agents": [
    {
      "name": "my-builder",
      "mode": "plan",
      "systemPrompt": "Vous êtes un ingénieur de build..."
    }
  ],
  "permissions": {
    "commands": ["npm", "git", "docker"]
  }
}

plugins.code:
# Configurer un serveur MCP dans opencode.json
{
  "mcpServers": {
    "my-db": {
      "command": "node",
      "args": ["mcp-server.js"],
      "env": { "DB_URL": "$DB_URL" }
    }
  }
}

labs.code:
# Activer les fonctionnalités expérimentales
opencode --labs "Essayer le nouvel agent de planification"

# Configurer dans opencode.json
{
  "experimental": {
    "enableNewAgent": true
  }
}
